CREATE TABLE organizations (id text PRIMARY KEY,name text NOT NULL,kind text NOT NULL,status text NOT NULL DEFAULT 'PENDING',synthetic boolean NOT NULL DEFAULT true);
CREATE TABLE users (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'PENDING');
CREATE TABLE wallets(address text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),CHECK(address=lower(address)));
CREATE TABLE memberships(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),organization_id text NOT NULL REFERENCES organizations(id),role text NOT NULL CHECK(role IN ('BORROWER','BUYER','LENDER','VERIFIER','ADMIN')),approved boolean NOT NULL DEFAULT false, UNIQUE(user_id,organization_id,role));
CREATE TABLE siwe_challenges(id text PRIMARY KEY,address text NOT NULL,message_hash text NOT NULL,browser_hash text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),wallet text NOT NULL,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE claims(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),buyer_org_id text NOT NULL REFERENCES organizations(id),claim_key text NOT NULL UNIQUE,hmac_key_version integer NOT NULL DEFAULT 1,invoice_namespace text NOT NULL,invoice_number text NOT NULL,version integer NOT NULL DEFAULT 1,workflow text NOT NULL DEFAULT 'DRAFT',terms jsonb NOT NULL,evidence jsonb NOT NULL,funding_hold boolean NOT NULL DEFAULT false,has_dispute boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,invoice_namespace,invoice_number));
CREATE TABLE claim_access(claim_id text NOT NULL REFERENCES claims(id),org_id text NOT NULL REFERENCES organizations(id),UNIQUE(claim_id,org_id));
CREATE TABLE claim_versions(id text PRIMARY KEY,claim_id text NOT NULL REFERENCES claims(id),version integer NOT NULL,snapshot jsonb NOT NULL,snapshot_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(claim_id,version));
CREATE TABLE documents(id text PRIMARY KEY,claim_id text NOT NULL REFERENCES claims(id),version integer NOT NULL,original_name text NOT NULL,storage_key text NOT NULL,sha256 text NOT NULL,commitment text NOT NULL,mime text NOT NULL,byte_size integer NOT NULL,extracted_text text,status text NOT NULL,retention_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE extracted_fields(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,fields jsonb NOT NULL);
CREATE TABLE attestations(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,actor_id text NOT NULL,method text NOT NULL,kind text NOT NULL,status text NOT NULL,evidence_ids jsonb NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consent_records(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,role text NOT NULL,signer text NOT NULL,nonce text NOT NULL,deadline integer NOT NULL,signature text NOT NULL,terms_hash text NOT NULL,revoked boolean NOT NULL DEFAULT false,UNIQUE(claim_id,version,role));
CREATE TABLE review_decisions(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,actor_id text NOT NULL,decision text NOT NULL,reason text NOT NULL,expires_at timestamptz NOT NULL,snapshot_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE policy_snapshots(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_runs(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,mode text NOT NULL,status text NOT NULL,stage text NOT NULL,input_hash text NOT NULL,result jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_steps(id text PRIMARY KEY,run_id text NOT NULL,step integer NOT NULL,stage text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_tasks(id text PRIMARY KEY,claim_id text NOT NULL,version integer NOT NULL,role text NOT NULL,kind text NOT NULL,status text NOT NULL DEFAULT 'OPEN',details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id text PRIMARY KEY,claim_id text NOT NULL,role text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chain_deployments(chain_id integer PRIMARY KEY,manifest jsonb NOT NULL);
CREATE TABLE transaction_intents(id text PRIMARY KEY,claim_id text NOT NULL,actor_id text NOT NULL,sender text NOT NULL,action text NOT NULL,status text NOT NULL,template jsonb NOT NULL,tx_hash text,replaces_id text,details jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chain_events(id text PRIMARY KEY,chain_id integer NOT NULL,tx_hash text NOT NULL,log_index integer NOT NULL,block_number numeric(78,0) NOT NULL,block_hash text NOT NULL,claim_key text,event_name text NOT NULL,args jsonb NOT NULL,canonical boolean NOT NULL DEFAULT true,UNIQUE(chain_id,tx_hash,log_index));
CREATE TABLE indexer_checkpoints(chain_id integer PRIMARY KEY,block_number numeric(78,0) NOT NULL,block_hash text NOT NULL,degraded boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE financial_projections(claim_key text PRIMARY KEY,chain_id integer NOT NULL,state jsonb NOT NULL,block_number numeric(78,0) NOT NULL,block_hash text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_records(scope text PRIMARY KEY,body_hash text NOT NULL,status integer NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id text PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_unpublished ON outbox(published_at);
CREATE TABLE audit_events(id text PRIMARY KEY,actor_id text NOT NULL,organization_id text,action text NOT NULL,target text NOT NULL,before_hash text,after_hash text,reason text,correlation_id text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_target_time ON audit_events(target,created_at);
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);
